  if (format == "date-time")
    return "^" + date + "[tT]" + time + "$";
  if (format == "uuid")
    return R"(^[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$)";
  if (format == "ipv4")
